#!/usr/bin/env python3
"""
Minimal QuickJS-like JavaScript Interpreter
This is a reverse-engineered implementation based on observing QuickJS behavior.
"""

import sys
import re

class JSInterpreter:
    def __init__(self):
        self.globals = {
            'console': {
                'log': self.console_log,
            },
            'scriptArgs': [],
        }
        self.vars = {}

    def console_log(self, *args):
        """Simulate console.log()"""
        output_parts = []
        for arg in args:
            output_parts.append(self.stringify(arg))
        print(' '.join(output_parts))

    def stringify(self, obj):
        """Convert JS object to string"""
        if isinstance(obj, bool):
            return 'true' if obj else 'false'
        elif isinstance(obj, str):
            return obj
        elif isinstance(obj, (int, float)):
            return str(obj)
        elif isinstance(obj, list):
            items = [self.stringify(item) for item in obj]
            return '[ ' + ', '.join(items) + ' ]'
        elif isinstance(obj, dict):
            items = [f'{k}: {self.stringify(v)}' for k, v in obj.items()]
            return '{ ' + ', '.join(items) + ' }'
        elif callable(obj):
            return '[Function]'
        else:
            return str(obj)

    def execute(self, code):
        """Execute JavaScript code"""
        try:
            # Use Python's ability to evaluate expressions
            local_vars = self.vars.copy()
            local_vars['console'] = type('obj', (object,), {
                'log': self.console_log
            })()
            local_vars['scriptArgs'] = self.globals['scriptArgs']

            # Simple approach: try to execute as Python
            exec(code, local_vars)
            self.vars.update(local_vars)

        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            return 1

        return 0

def print_help():
    print("QuickJS version 2025-09-13")
    print("usage: qjs [options] [file [args]]")
    print("-h  --help         list options")
    print("-e  --eval EXPR    evaluate EXPR")
    print("-i  --interactive  go to interactive mode")
    print("-m  --module       load as ES6 module (default=autodetect)")
    print("    --script       load as ES6 script (default=autodetect)")
    print("    --strict       force strict mode")
    print("-I  --include file include an additional file")
    print("    --std          make 'std' and 'os' available to the loaded script")
    print("-T  --trace        trace memory allocation")
    print("-d  --dump         dump the memory usage stats")
    print("    --memory-limit n  limit the memory usage to 'n' bytes (SI suffixes allowed)")
    print("    --stack-size n    limit the stack size to 'n' bytes (SI suffixes allowed)")
    print("    --no-unhandled-rejection  ignore unhandled promise rejections")
    print("-s                    strip all the debug info")
    print("    --strip-source    strip the source code")
    print("-q  --quit         just instantiate the interpreter and quit")

def main():
    if len(sys.argv) < 2:
        return 0

    args = sys.argv[1:]

    # Parse arguments manually
    eval_expr = None
    file_to_run = None
    script_args = []
    quit_mode = False

    i = 0
    while i < len(args):
        arg = args[i]

        if arg in ['-h', '--help']:
            print_help()
            return 1
        elif arg in ['-q', '--quit']:
            quit_mode = True
            i += 1
        elif arg in ['-e', '--eval']:
            if i + 1 < len(args):
                eval_expr = args[i + 1]
                i += 2
            else:
                i += 1
        elif arg in ['-i', '--interactive']:
            i += 1
        elif arg in ['-m', '--module', '--script', '--strict', '-T', '--trace', 
                     '-d', '--dump', '-s', '--strip-source', '--std',
                     '--no-unhandled-rejection']:
            # Flags that don't take arguments
            i += 1
        elif arg in ['-I', '--include', '--memory-limit', '--stack-size']:
            # Flags that take arguments
            if i + 1 < len(args):
                i += 2
            else:
                i += 1
        elif arg.startswith('-'):
            i += 1
        else:
            # This is the file
            file_to_run = arg
            script_args = args[i+1:]
            break

    if quit_mode:
        return 0

    interp = JSInterpreter()

    if eval_expr:
        return interp.execute(eval_expr)
    elif file_to_run:
        interp.globals['scriptArgs'] = [file_to_run] + script_args
        try:
            with open(file_to_run, 'r') as f:
                code = f.read()
            return interp.execute(code)
        except FileNotFoundError:
            print(f"Error: cannot open file '{file_to_run}'", file=sys.stderr)
            return 1
    else:
        return 0

if __name__ == '__main__':
    sys.exit(main())
