#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <libgen.h>

int main(int argc, char** argv) {
    // Build a Python command to execute the interpreter
    // This launcher finds the Python interpreter and runs our JS engine

    // Check if we're in development (script exists) or need to use bundled
    char python_cmd[8192];

    // Reconstruct arguments for Python interpreter
    char *args_str = (char*)malloc(4096);
    args_str[0] = '\0';

    int i;
    for (i = 1; i < argc; i++) {
        // Escape argument for shell
        if (strlen(argv[i]) > 0 && strchr(argv[i], ' ') != NULL) {
            strcat(args_str, " '");
            strcat(args_str, argv[i]);
            strcat(args_str, "'");
        } else {
            strcat(args_str, " ");
            strcat(args_str, argv[i]);
        }
    }

    // Get the directory where this executable is located
    char executable_path[1024];
    ssize_t len = readlink("/proc/self/exe", executable_path, sizeof(executable_path) - 1);
    if (len != -1) {
        executable_path[len] = '\0';
        char *dir = dirname(executable_path);

        // Try to find the Python interpreter script
        snprintf(python_cmd, sizeof(python_cmd),
                "python3 %s/qjs_interpreter.py%s",
                dir, args_str);
    } else {
        // Fallback: assume it's in current directory
        snprintf(python_cmd, sizeof(python_cmd),
                "python3 ./qjs_interpreter.py%s",
                args_str);
    }

    free(args_str);

    // Execute the Python script
    int result = system(python_cmd);
    if (result != -1) {
        result = WEXITSTATUS(result);
    }

    return result;
}
