int main(int argc, char *argv[]) {
    PyObject *pModule, *pFunc, *pArgs, *pValue;
    const char *module_path;

    // Initialize Python
    Py_Initialize();

    // Add current directory to Python path
    PyRun_SimpleString("import sys");
    PyRun_SimpleString("sys.path.insert(0, '.')");

    // Import our qjs_interpreter module
    PyObject *pName = PyUnicode_DecodeFSDefault("qjs_interpreter");
    pModule = PyImport_Import(pName);
    Py_DECREF(pName);

    if (pModule != NULL) {
        // Get the main function
        pFunc = PyObject_GetAttrString(pModule, "main");

        if (pFunc && PyCallable_Check(pFunc)) {
            // Prepare arguments
            PyObject *argv_list = PyList_New(argc);
            int i;
            for (i = 0; i < argc; i++) {
                PyList_SetItem(argv_list, i, PyUnicode_FromString(argv[i]));
            }

            // Create argument tuple
            PyObject *pArgs = PyTuple_Pack(1, argv_list);

            // Call main(argv)
            pValue = PyObject_CallObject(pFunc, pArgs);

            int ret_code = 0;
            if (pValue != NULL) {
                if (PyLong_Check(pValue)) {
                    ret_code = PyLong_AsLong(pValue);
                }
                Py_DECREF(pValue);
            } else {
                PyErr_Print();
                ret_code = 1;
            }

            Py_DECREF(pArgs);
            Py_DECREF(argv_list);
            Py_DECREF(pFunc);
            Py_DECREF(pModule);
            Py_Finalize();
            return ret_code;
        } else {
            if (PyErr_Occurred())
                PyErr_Print();
            fprintf(stderr, "Cannot find function \"main\"\n");
            Py_XDECREF(pFunc);
            Py_DECREF(pModule);
        }
    } else {
        PyErr_Print();
        fprintf(stderr, "Failed to load \"qjs_interpreter\"\n");
    }

    Py_Finalize();
    return 1;
}
