#!/usr/bin/env python3
"""
Minimal QuickJS-like JavaScript Interpreter
Reverse-engineered based on QuickJS behavior.
"""

import sys
import re
import json

class JSValue:
    """Represents a JavaScript value"""
    def __init__(self, value, js_type=None):
        self.value = value
        self.js_type = js_type or self._infer_type()

    def _infer_type(self):
        if isinstance(self.value, bool):
            return 'boolean'
        elif isinstance(self.value, str):
            return 'string'
        elif isinstance(self.value, (int, float)):
            return 'number'
        elif isinstance(self.value, list):
            return 'array'
        elif isinstance(self.value, dict):
            return 'object'
        elif callable(self.value):
            return 'function'
        elif self.value is None:
            return 'null'
        else:
            return 'object'

    def to_js_string(self):
        """Convert to JavaScript string representation"""
        if isinstance(self.value, bool):
            return 'true' if self.value else 'false'
        elif isinstance(self.value, str):
            return self.value
        elif isinstance(self.value, (int, float)):
            return str(self.value)
        elif isinstance(self.value, list):
            items = []
            for item in self.value:
                if isinstance(item, JSValue):
                    items.append(item.to_js_string())
                else:
                    items.append(str(item))
            return '[ ' + ', '.join(items) + ' ]'
        elif isinstance(self.value, dict):
            items = []
            for k, v in self.value.items():
                if isinstance(v, JSValue):
                    val_str = v.to_js_string()
                else:
                    val_str = str(v)
                items.append(f'{k}: {val_str}')
            return '{ ' + ', '.join(items) + ' }'
        elif self.value is None:
            return 'null'
        else:
            return '[object Object]'

class JSInterpreter:
    def __init__(self):
        self.globals = {}
        self.locals = {}
        self.setup_builtins()

    def setup_builtins(self):
        """Setup built-in functions and objects"""
        self.globals['console'] = {
            'log': lambda *args: self.console_log(*args)
        }
        self.globals['undefined'] = None
        self.globals['null'] = None
        self.globals['true'] = True
        self.globals['false'] = False

    def console_log(self, *args):
        """Implement console.log()"""
        parts = []
        for arg in args:
            if isinstance(arg, dict) and 'log' in arg:
                # It's probably console object
                continue
            elif isinstance(arg, JSValue):
                parts.append(arg.to_js_string())
            elif isinstance(arg, bool):
                parts.append('true' if arg else 'false')
            elif isinstance(arg, list):
                items = []
                for item in arg:
                    if isinstance(item, bool):
                        items.append('true' if item else 'false')
                    else:
                        items.append(str(item))
                parts.append('[ ' + ', '.join(items) + ' ]')
            elif isinstance(arg, dict):
                items = []
                for k, v in arg.items():
                    if isinstance(v, bool):
                        val_str = 'true' if v else 'false'
                    else:
                        val_str = str(v)
                    items.append(f'{k}: {val_str}')
                parts.append('{ ' + ', '.join(items) + ' }')
            else:
                parts.append(str(arg))
        print(' '.join(parts))

    def transpile_js_to_python(self, code):
        """Convert JavaScript code to Python-like code that can be executed"""
        # This is a very simple transpiler
        # It handles basic cases

        # Replace let/const with simple assignments
        code = re.sub(r'\blet\s+', '', code)
        code = re.sub(r'\bconst\s+', '', code)
        code = re.sub(r'\bvar\s+', '', code)

        # Replace console.log calls with our function
        # But we need to be careful to not break strings

        # Replace function declarations
        code = re.sub(r'\bfunction\s+(\w+)\s*\(', r'def \1(', code)

        # Replace => arrow functions with lambda
        # This is simplistic but works for basic cases
        code = re.sub(r'(\w+)\s*=>\s*', r'lambda \1: ', code)
        code = re.sub(r'\((.*?)\)\s*=>\s*', r'lambda \1: ', code)

        # Replace && and || with 'and' and 'or'
        code = re.sub(r'\s+&&\s+', ' and ', code)
        code = re.sub(r'\s+\|\|\s+', ' or ', code)
        code = re.sub(r'!(\w)', r'not \1', code)

        return code

    def execute(self, code):
        """Execute JavaScript code"""
        try:
            # Transpile to Python
            python_code = self.transpile_js_to_python(code)

            # Create execution environment
            exec_env = {'__builtins__': {}}
            exec_env.update(self.globals)
            exec_env.update(self.locals)

            # Handle console.log specially
            original_log = self.console_log
            console_obj = {
                'log': original_log
            }
            exec_env['console'] = console_obj

            # Execute the code
            exec(python_code, exec_env, exec_env)

            # Update locals
            self.locals.update(exec_env)

            return 0

        except SyntaxError as e:
            print(f"SyntaxError: {e}", file=sys.stderr)
            return 1
        except Exception as e:
            print(f"Error: {type(e).__name__}: {e}", file=sys.stderr)
            return 1

    def run_file(self, filepath, args):
        """Run a JavaScript file"""
        try:
            with open(filepath, 'r') as f:
                code = f.read()

            # Set up scriptArgs
            self.globals['scriptArgs'] = [filepath] + args

            return self.execute(code)
        except FileNotFoundError:
            print(f"Error: cannot open file '{filepath}'", file=sys.stderr)
            return 1

def print_help():
    """Print help message matching QuickJS"""
    print("QuickJS version 2025-09-13")
    print("usage: qjs [options] [file [args]]")
    print("-h  --help         list options")
    print("-e  --eval EXPR    evaluate EXPR")
    print("-i  --interactive  go to interactive mode")
    print("-m  --module       load as ES6 module (default=autodetect)")
    print("    --script       load as ES6 script (default=autodetect)")
    print("    --strict       force strict mode")
    print("-I  --include file include an additional file")
    print("    --std          make 'std' and 'os' available to the loaded script")
    print("-T  --trace        trace memory allocation")
    print("-d  --dump         dump the memory usage stats")
    print("    --memory-limit n  limit the memory usage to 'n' bytes (SI suffixes allowed)")
    print("    --stack-size n    limit the stack size to 'n' bytes (SI suffixes allowed)")
    print("    --no-unhandled-rejection  ignore unhandled promise rejections")
    print("-s                    strip all the debug info")
    print("    --strip-source    strip the source code")
    print("-q  --quit         just instantiate the interpreter and quit")

def main(argv=None):
    """Main entry point"""
    if argv is None:
        argv = sys.argv

    if len(argv) < 2:
        # No arguments
        return 0

    # Parse arguments
    args = argv[1:]

    eval_expr = None
    file_to_run = None
    script_args = []
    quit_mode = False
    interactive = False

    i = 0
    while i < len(args):
        arg = args[i]

        if arg in ['-h', '--help']:
            print_help()
            return 1  # QuickJS returns 1 for --help
        elif arg in ['-q', '--quit']:
            quit_mode = True
            i += 1
        elif arg in ['-i', '--interactive']:
            interactive = True
            i += 1
        elif arg in ['-e', '--eval']:
            if i + 1 < len(args):
                eval_expr = args[i + 1]
                i += 2
            else:
                i += 1
        elif arg in ['-m', '--module', '--script', '--strict', '-T', '--trace',
                     '-d', '--dump', '-s', '--strip-source', '--std',
                     '--no-unhandled-rejection']:
            # Flags without arguments
            i += 1
        elif arg in ['-I', '--include', '--memory-limit', '--stack-size']:
            # Flags with arguments
            if i + 1 < len(args):
                i += 2
            else:
                i += 1
        elif arg.startswith('-'):
            # Unknown flag
            i += 1
        else:
            # This is the file
            file_to_run = arg
            script_args = args[i+1:]
            break

    # Handle modes
    if quit_mode:
        return 0

    interp = JSInterpreter()

    if eval_expr:
        return interp.execute(eval_expr)
    elif file_to_run:
        return interp.run_file(file_to_run, script_args)
    elif interactive:
        # Simple REPL
        while True:
            try:
                line = input("qjs> ")
                if line.strip():
                    interp.execute(line)
            except KeyboardInterrupt:
                print()
                return 0
            except EOFError:
                return 0
    else:
        # Default: read from stdin or do nothing
        return 0

if __name__ == '__main__':
    sys.exit(main())
