"""
Minimal QuickJS-like JavaScript Interpreter
Reverse-engineered based on QuickJS behavior.
"""

import sys
import re

class Console:
    """JavaScript console object"""
    def __init__(self, interpreter):
        self.interpreter = interpreter

    def log(self, *args):
        """console.log() implementation"""
        output = []
        for arg in args:
            output.append(self.interpreter._stringify(arg))
        print(' '.join(output))

class SimpleInterpreter:
    def __init__(self):
        self.variables = {}
        self.console = Console(self)

    def _stringify(self, obj):
        """Convert object to string for display"""
        if isinstance(obj, bool):
            return 'true' if obj else 'false'
        elif isinstance(obj, str):
            return obj
        elif isinstance(obj, (int, float)):
            # Python will print float as "3.0" but we want "3"
            if isinstance(obj, float) and obj == int(obj):
                return str(int(obj))
            return str(obj)
        elif isinstance(obj, list):
            items = [self._stringify(item) for item in obj]
            return '[ ' + ', '.join(items) + ' ]'
        elif isinstance(obj, dict):
            items = []
            for k, v in obj.items():
                val_str = self._stringify(v)
                items.append(f'{k}: {val_str}')
            return '{ ' + ', '.join(items) + ' }'
        elif obj is None:
            return 'null'
        else:
            return str(obj)

    def execute(self, code):
        """Execute code"""
        try:
            # Prepare execution environment
            env = {
                '__builtins__': {},
                'scriptArgs': self.variables.get('scriptArgs', []),
                'console': self.console,
            }
            env.update(self.variables)

            # Simple transpilation
            py_code = self._transpile(code)

            # Execute
            exec(py_code, env, env)

            # Store updated variables (but not builtins)
            for k, v in env.items():
                if not k.startswith('__') and k not in ['console', 'scriptArgs']:
                    self.variables[k] = v

            return 0
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            return 1

